/** The one session a store holds, for asserting what survived a close. */
export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
  return (await store.get(sessionId)) as ChatSession | undefined;
}

/** Terminates tracked clients and waits for each server's socket set to drain before stopping it. */
export async function closeSocketsAndServers(trackedClients: WebSocket[], trackedServers: HalServer[]): Promise<void> {
  for (const client of trackedClients.splice(0)) client.terminate();
  for (const hal of trackedServers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

/** Polls a predicate briefly, for teardown waiting on server-side socket close events. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** A store with only the five required members, so optional ones can be added, replaced or omitted per test. */
export function delegatingStore(inner: SessionStore): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
  };
}

